fn readExact(stream: anytype, buf: []u8) !void {
    var n: usize = 0;
    while (n < buf.len) {
        const got = try stream.read(buf[n..]);
        if (got == 0) return error.UnexpectedEof; // short read from a hostile client
        n += got;
    }
}

const AUTH_VERSION: u8 = 0x01;

// RFC 1929 subnegotiation. Returns true only if the credential matches.
fn authenticate(stream: anytype, want_user: []const u8, want_pass: []const u8) !bool {
    var head: [2]u8 = undefined;
    try readExact(stream, &head); // [version=0x01][ulen]
    if (head[0] != AUTH_VERSION) return error.BadVersion;

    var ubuf: [255]u8 = undefined; // ulen is one byte, so 255 is the hard ceiling
    try readExact(stream, ubuf[0..head[1]]);

    var plen: [1]u8 = undefined;
    try readExact(stream, &plen);
    var pbuf: [255]u8 = undefined;
    try readExact(stream, pbuf[0..plen[0]]);

    const ok = std.mem.eql(u8, ubuf[0..head[1]], want_user) and
        std.mem.eql(u8, pbuf[0..plen[0]], want_pass);
    try stream.writeAll(&[_]u8{ AUTH_VERSION, if (ok) 0x00 else 0x01 });
    return ok;
}

// A read+write stream backed by memory, so we can drive the whole exchange offline.
const MemStream = struct {
    fbs: std.io.FixedBufferStream([]const u8),
    out: std.ArrayListUnmanaged(u8) = .{},
    alloc: std.mem.Allocator,
    fn read(self: *MemStream, buf: []u8) !usize { return self.fbs.reader().read(buf); }
    fn writeAll(self: *MemStream, b: []const u8) !void { try self.out.appendSlice(self.alloc, b); }
};

