const ConnLimiter = struct {
    active: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
    max: u32,

    // Optimistically claim a slot; back out atomically if we overshot the ceiling.
    fn acquire(self: *ConnLimiter) bool {
        const prev = self.active.fetchAdd(1, .acq_rel);
        if (prev >= self.max) {
            _ = self.active.fetchSub(1, .acq_rel); // we never really got in
            return false;
        }
        return true;
    }
    fn release(self: *ConnLimiter) void {
        _ = self.active.fetchSub(1, .acq_rel);
    }
};

