const ProxyError = error{
    GeneralFailure, ConnectionNotAllowed, NetworkUnreachable,
    HostUnreachable, ConnectionRefused, CommandNotSupported, AddressTypeNotSupported,
};

fn replyToError(code: u8) ?ProxyError {
    return switch (code) {
        0x00 => null,
        0x02 => error.ConnectionNotAllowed,
        0x03 => error.NetworkUnreachable,
        0x04 => error.HostUnreachable,
        0x05 => error.ConnectionRefused,
        0x07 => error.CommandNotSupported,
        0x08 => error.AddressTypeNotSupported,
        else => error.GeneralFailure,
    };
}

fn connectThrough(proxy: std.net.Address, host: []const u8, port: u16) !std.net.Stream {
    std.debug.assert(host.len <= 255); // domain length is a single byte on the wire
    const stream = try std.net.tcpConnectToAddress(proxy);
    errdefer stream.close();

    try stream.writeAll(&[_]u8{ 0x05, 0x01, 0x00 }); // greeting: 1 method, no-auth
    var greet: [2]u8 = undefined;
    try readExact(stream, &greet);
    if (greet[0] != 0x05 or greet[1] != 0x00) return error.NoAcceptableMethod;

    var req: std.BoundedArray(u8, 262) = .{};
    try req.appendSlice(&[_]u8{ 0x05, 0x01, 0x00, 0x03, @intCast(host.len) }); // CONNECT, domain
    try req.appendSlice(host);
    var port_be: [2]u8 = undefined;
    std.mem.writeInt(u16, &port_be, port, .big);
    try req.appendSlice(&port_be);
    try stream.writeAll(req.slice());

    var head: [4]u8 = undefined; // [ver][code][rsv][atyp]
    try readExact(stream, &head);
    if (replyToError(head[1])) |e| return e;

    const tail: usize = switch (head[3]) { // skip the bound address we don't need
        0x01 => 4 + 2,
        0x04 => 16 + 2,
        0x03 => blk: {
            var l: [1]u8 = undefined;
            try readExact(stream, &l);
            break :blk l[0] + @as(usize, 2);
        },
        else => return error.AddressTypeNotSupported,
    };
    var scratch: [256]u8 = undefined;
    try readExact(stream, scratch[0..tail]);
    return stream; // live tunnel, ready to use
}
```

The honest part is `replyToError`: a non-zero reply does not become a vague \

